package android.content;
public class IntentFilter { private final java.util.ArrayList<String> actions=new java.util.ArrayList<String>(); public IntentFilter() {} public IntentFilter(String a) { addAction(a); } public IntentFilter(String a,String type) { addAction(a); } public void addAction(String a) { actions.add(a); } public boolean hasAction(String a) { return actions.contains(a); } public int countActions() { return actions.size(); } public String getAction(int i) { return actions.get(i); } public void addCategory(String c) {} public void addDataScheme(String s) {} public void addDataType(String s) throws MalformedMimeTypeException {} public static class MalformedMimeTypeException extends Exception { public MalformedMimeTypeException() {} public MalformedMimeTypeException(String s) { super(s); } } }
